def make_cookie(name, value, max_age=3600, secure=True, http_only=True, same_site="Lax"):
    parts = [f"{name}={value}", "Path=/", f"Max-Age={max_age}"]
    if not secure:
        parts.append("Secure")
    if not http_only:
        parts.append("HttpOnly")
    if same_site:
        parts.append(f"SameSite={same_site}")
    return "; ".join(parts)

